void _printKeyStatus() {
  final keys = config.secureKeys;
  final names = <String>{
    for (final spec in providerCatalog.values) ...spec.apiKeyEnvNames,
    ...?keys?.names,
  }.toList()..sort();
  for (final name in names) {
    final inEnv = config.envVarIsSet?.call(name) ?? false;
    final inStore = keys != null && keys.read(name) != null;
    final source = inEnv
        ? 'env'
        : inStore
        ? keys.label ?? 'keychain'
        : 'not set';
    io.writeln('  $name: $source');
  }
  if (keys == null || !keys.available) {
    io.writeln(
      'secure storage unavailable on this host — keys resolve from the '
      'environment only',
    );
  } else {
    io.writeln(
      'secure storage: ${keys.label} '
      '(/key set <NAME> <value>, /key delete <NAME>)',
    );
  }
  // gh-1059 review: save degradations can only happen AFTER boot (every
  // `keys.save()` call site is interactive), so the boot summary can
  // never see them — the status print is where they are live.
  if (keys != null && keys.saveFailures > 0) {
    final last = keys.lastSaveError;
    io.writeln(
      'warning: ${keys.saveFailures} secure-store save(s) degraded to '
      'session-only${last == null ? '' : ' ($last)'} — re-enter the keys '
      'once the store is writable',
    );
  }
}

