  Future<String?> _persistExtFlowKey(String baseUrl, String? apiKey) async {
    if (apiKey == null || apiKey.isEmpty) return null;
    final keyName = CustomProviderRegistry.keyNameFor(baseUrl);
    final keys = config.secureKeys;
