    final baseUrl = answered['baseUrl'] ?? '';
    if (baseUrl.isEmpty) return io.writeln('canceled');
    final keyName = await _persistExtFlowKey(baseUrl, answered['apiKey']);
    var providerName = answered['providerName'] ?? '';
    if (providerName.isEmpty) {
