    final last = keys.lastSaveError;
    io.writeln(
      'warning: ${keys.saveFailures} secure-store save(s) degraded to '
      'session-only${last == null ? '' : ' ($last)'} — re-enter the keys '
      'once the store is writable',
    );
  }
}

