    flagSystemPrompt = loadPromptFile(
      systemPromptFile,
      homeDir: home,
      baseDir: Directory.current.path,
      source: '--system-prompt-file',
    );
  } on ConfigException catch (error) {
    _fail(error.message);
  }
}

