    for (final base in bases) {
      if (entry.key == base) return false;
      if (entry.key.length > base.length &&
          entry.key.startsWith(base) &&
          entry.key.codeUnitAt(base.length) == 0x5f &&
          int.tryParse(entry.key.substring(base.length + 1)) != null) {
        return false;
      }
    }
  }
  return true;
