  final cli = cliFor(
    fake.call,
    envVarValue: (_) => null,
    onProviderChanged: (kind, key) async {
      changes.add((kind, key));
    },
  );
  final run = cli.run();

  io.sendLine('/provider custom');
  await waitForIt(() => io.out.toString().contains('type a number:'));
