  expect(store.map['FA_KEY_PROXY_EXAMPLE_COM_IRA2'], 'sk-two');
  final entries = cli.config.customProviders?.entries ?? const [];
  expect(
    entries.map((e) => e.keyName).toSet().length,
    entries.length,
    reason: 'every entry owns a distinct key slot',
  );
});

