      );
      expect(host.applied, isNotNull);
      expect(host.applied!.token, 'typed-after');
    });

    test('cancelling the key-step picker aborts the edit', () async {
      final host = _ScriptedHost()
        ..optionAnswers.addAll(['openai', null])
        ..lineAnswers.addAll(['', '']);
