test('two accounts on one endpoint keep separate keys', () async {
  final fake = FakeStreamFunction([textTurn('ok')]);
  final store = FakeSecureKeyStore();
  final cache = SecureKeyCache(store);
  await cache.probe();
  final cli = cliFor(
