  await waitForIt(
    () => io.out.toString().contains('no model list from the endpoint'),
  );
  io.sendLine('my-local-model');
  await waitForIt(
    () => io.out.toString().contains('switched provider to openai'),
  );
  io.sendLine('/exit');
  await run;

  final output = io.out.toString();
  final model = cli.agent.state.model;
