      expect(await cache.save('FA_KEY_A', 'k3'), isTrue);

      expect(cache.failedSaveNames, ['FA_KEY_B']);
      expect(cache.saveFailureDiagnostic('FA_KEY_A'), isNull);
      expect(cache.read('FA_KEY_A'), 'k3');
