 /// on its own. Returns the repair's exit code (null when declined or
 /// the shell is unavailable).
 Future<int?> _offerDefaultKeychainRepair() async {
   io.writeln(
     'repair now? runs: security default-keychain -s '
     '~/Library/Keychains/login.keychain-db [y/N]',
   );
   final answer = await _promptLine('> ');
   if (answer == null || answer.trim().toLowerCase() != 'y') {
     io.writeln('skipped — ' + ...advisory);
     return null;
   }
   final result = await config.env.exec(
     'security default-keychain -s ~/Library/Keychains/login.keychain-db',
   );
   switch (result) {
     case Ok(value: final r): return r.exitCode;
     case Err(): io.writeln('could not run the repair command'); return null;
   }
