  final commands = <String>[];

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    commands.add(command);
    store.writeError = null;
    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
