      final cache = SecureKeyCache(store);
      await cache.probe();
      final cli = cliFor(fake.call, secureKeys: cache);
      final run = cli.run();

      // /key set on the same failing store.
      io.sendLine('/key set $slot sk-ira-secret-789');
      await waitForIt(
        () => io.out.toString().contains('could not save $slot'),
