        activeCustomName: 'z.ai',
        registry: CustomProviderRegistry([
          CustomProviderEntry(
            name: 'z.ai',
            apiType: 'zai',
            baseUrl: zaiUrl,
            modelId: 'glm-5.3-flash',
            keyName: doubledZaiKeyName,
          ),
        ]),
      );
